rule "10 - Evaluation: Self-Monitoring Logs - Parser Graylog"
when
    to_string($message.filebeat_event_source_product) == "self-monitoring-compose-stack"

then
    let this_log = multi_grok(
        value: to_string($message.message), 
        patterns: [
            "^%{TIMESTAMP_ISO8601:event_received}%{SPACE}%{LOGLEVEL}%{SPACE}\\[%{DATA}\\]%{SPACE}\\[%{TIMESTAMP_ISO8601:event_created}\\]%{SPACE}\\[%{LOGLEVEL:event_severity}%{SPACE}\\]%{SPACE}\\[%{DATA:application_component}\\]%{SPACE}\\[%{DATA:container_name}\\]%{DATA:message}$", //DATANODE
            "^%{TIMESTAMP_ISO8601:event_received}%{SPACE}%{LOGLEVEL:event_severity}%{SPACE}:%{SPACE}%{DATA:application_component}%{SPACE}-%{SPACE}%{DATA:message}$"
        ], 
        only_named_captures: true
    );

    set_fields(this_log); 

    rename_fields(
        fields: {
            filebeat_event_source_product: "event_source_product"
        }
    );

    remove_multiple_fields(
        pattern: "filebeat_.*", 
        names: []
    );

    set_field("event_received", to_date(flex_parse_date(to_string($message.event_received))));

end
